    for color, (_, cr, cc) in pieces.items():
        q = ("T" if cr < h / 2 else "B") + ("L" if cc < w / 2 else "R")
        by_quad[q] = color

    if marker_quad == "BL":
        destination = {"TL": by_quad.get("BL"), "TR": by_quad.get("BR"),
                       "BL": by_quad.get("TR"), "BR": by_quad.get("TL")}
    elif marker_quad == "TR":
        destination = {"TL": by_quad.get("TR"), "TR": by_quad.get("TL"),
