                      if grid[r][c] == 7 or grid[r][c] == 5)
            flip_v = mr - rr > d // 2
            flip_h = mc - cc > d // 2
            if flip_v:
                mat.reverse()
                rr = len(mat) - (rr + d)
            if flip_h:
                mat = [row[::-1] for row in mat]
                cc = len(mat[0]) - (cc + d)
        prepared[color] = (mat, rr, cc)

    out = [[0] * (2 * d) for _ in range(2 * d)]
    anchors = {"TL": (0, 0), "TR": (0, d), "BL": (d, 0), "BR": (d, d)}
    # Nearby pieces may overlap at their extensions; later pieces take precedence.
    order = ["TL", "BL", "BR", "TR"]
    for q in order:
        color = destination.get(q)
        if color is None or color not in prepared:
            continue
        mat, rr, cc = prepared[color]
        ar, ac = anchors[q]
        sr, sc = ar - rr, ac - cc
        for r, row in enumerate(mat):
            for c, value in enumerate(row):
                y, x = sr + r, sc + c
                if value and 0 <= y < 2 * d and 0 <= x < 2 * d:
                    out[y][x] = value
    return out
